// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Bundles) predicate.Bundles {
	return predicate.Bundles(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Bundles) predicate.Bundles {
	return predicate.Bundles(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Bundles) predicate.Bundles {
	return predicate.Bundles(sql.NotPredicates(p))
}
